CREATE TABLE public.reminders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),branch_id text NOT NULL REFERENCES public.branches(id),title text NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 200),note text NOT NULL DEFAULT '' CHECK (length(note)<=1000),remind_date date NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),done_at timestamptz,done_by uuid);
GRANT SELECT ON public.reminders TO authenticated;
GRANT ALL ON public.reminders TO service_role;
ALTER TABLE public.reminders ENABLE ROW LEVEL SECURITY;
CREATE POLICY reminders_read ON public.reminders FOR SELECT TO authenticated USING (public.staff_can('Create bills',branch_id) OR public.staff_can('Collect repayments',branch_id));
CREATE FUNCTION public.add_reminder(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE b text:=p->>'branch_id';rid uuid;BEGIN IF NOT (public.staff_can('Create bills',b) OR public.staff_can('Collect repayments',b)) THEN RAISE EXCEPTION 'Permission required';END IF;INSERT INTO public.reminders(branch_id,title,note,remind_date,created_by) VALUES(b,trim(p->>'title'),coalesce(p->>'note',''),(p->>'remind_date')::date,auth.uid()) RETURNING id INTO rid;INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),b,'Reminders','Added','Added reminder "'||trim(p->>'title')||'" for '||(p->>'remind_date'),rid::text);RETURN rid;END$$;
CREATE FUNCTION public.complete_reminder(rid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE r public.reminders;BEGIN SELECT * INTO r FROM public.reminders WHERE id=rid FOR UPDATE;IF NOT FOUND OR NOT (public.staff_can('Create bills',r.branch_id) OR public.staff_can('Collect repayments',r.branch_id)) THEN RAISE EXCEPTION 'Permission required';END IF;IF r.done_at IS NOT NULL THEN RAISE EXCEPTION 'Reminder already done';END IF;UPDATE public.reminders SET done_at=now(),done_by=auth.uid() WHERE id=rid;INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),r.branch_id,'Reminders','Completed','Marked reminder "'||r.title||'" done',rid::text);END$$;
REVOKE EXECUTE ON FUNCTION public.add_reminder(jsonb),public.complete_reminder(uuid) FROM anon,public;
GRANT EXECUTE ON FUNCTION public.add_reminder(jsonb),public.complete_reminder(uuid) TO authenticated;